import{_ as a,o as t,c as i,ak as n}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy manuscript working draft","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","frontmatter":{"title":"Chainy manuscript working draft","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","source":"docs/archive/pre-v2-adoption-2026-10-23/docs/manuscript-working-draft.md","category":"Archive","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/manuscript-working-draft.md","filePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/manuscript-working-draft.md"}'),o={name:"content/docs/archive/pre-v2-adoption-2026-10-23/docs/manuscript-working-draft.md"};function r(s,e,c,d,l,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<div><h1 id="chainy-manuscript-working-draft">Chainy manuscript working draft<a class="header-anchor" href="#chainy-manuscript-working-draft" aria-label="Link to this section">​</a></h1><blockquote><p>Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/readme.html">adoption archive</a>.</p></blockquote><p>Updated October 12, 2026 for Christian&#39;s adopted technical design. Sean owns the manuscript; Miguel supports formatting and figures. This is a drafting foundation, not a completed school submission.</p><p>Use the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/manuscript-evidence-map.html">official outline</a> for required numbering and appendices. Verified literature, actual prototype evidence, study details and results must still be supplied.</p><h2 id="chapter-i--introduction">Chapter I — Introduction<a class="header-anchor" href="#chapter-i--introduction" aria-label="Link to this section">​</a></h2><h3 id="project-context">Project context<a class="header-anchor" href="#project-context" aria-label="Link to this section">​</a></h3><p>Chainy is intended for learners aged 12–17, especially learners in low-income and remote communities with limited technology access. It introduces selected foundational Web3, Blockchain and artificial intelligence concepts through an offline Android educational game. The audience and access priorities are project decisions; they do not establish measured needs at the pilot school without supporting evidence.</p><h3 id="purpose-and-description">Purpose and description<a class="header-anchor" href="#purpose-and-description" aria-label="Link to this section">​</a></h3><p>The proposed system uses explorable 3D learning levels, instructional interactions and three mini-game formats: Quiz, Wordle and BlockMatch. Learners encounter an explanation, complete an activity, receive feedback and retain progress locally. Unity runs presentation and gameplay; SQLite stores local profiles, learning records and progress. The architecture requires no external authentication, backend or cloud service for play.</p><p>The game formats serve different purposes. Quiz checks understanding, Wordle can reinforce taught vocabulary, and BlockMatch can practice meaningful relationships. Each activity requires a stated objective and an explanation of its result. Whether these activities support learning must be evaluated rather than assumed from engagement or completion.</p><h3 id="objectives">Objectives<a class="header-anchor" href="#objectives" aria-label="Link to this section">​</a></h3><p>The general objective is to design, develop and evaluate an offline educational game introducing selected emerging-technology concepts to the intended learners.</p><p>Proposed specific objectives are to deliver the three agreed game modes within usable learning levels; provide accurate explanations and feedback; retain separate local profiles and reliable progress; verify operation on selected Android devices; and evaluate the delivered system using the school&#39;s approved procedure.</p><h3 id="scope-and-delimitation">Scope and delimitation<a class="header-anchor" href="#scope-and-delimitation" aria-label="Link to this section">​</a></h3><p>The first version is single-player and English-first. Exact topic, level and content quantities are to be frozen by the Design Lead and Docs Lead. A learner code identifies a local profile; it does not authenticate a person or restore another device&#39;s save. Teacher collection is separate from offline gameplay.</p><p>The previous generated ordering/replica/classifier/grid-agent implementation plan is replaced. Teaching AI does not require a trained model or cloud AI in this game. Device support and learning effectiveness remain subject to actual tests.</p><h3 id="significance">Significance<a class="header-anchor" href="#significance" aria-label="Link to this section">​</a></h3><p>The intended contribution is an accessible offline learning experience, with clear activities for learners, supervised use for teachers and documented implementation/evaluation evidence for the team. The final manuscript must support these claims with actual findings and acknowledge the limits of its study.</p><h2 id="chapter-ii--literature-and-technical-background">Chapter II — Literature and technical background<a class="header-anchor" href="#chapter-ii--literature-and-technical-background" aria-label="Link to this section">​</a></h2><p>Sean must build a verified literature review on game-based learning, vocabulary/concept activities, introductory technology education, offline mobile access, usability and evaluation. For each study record its participants, method, findings, limitations and relevance. Do not claim novelty or effectiveness from the game concept alone.</p><p>Use Christian&#39;s <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/technical-design.html">technical design</a> to explain the project&#39;s component responsibilities and <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/design/database-schema.html">database reference</a> for local records. Technical documentation supports implementation facts; it does not substitute for evidence about educational outcomes.</p><p>Keep terms consistent: a module groups lessons; a lesson has an objective; a mini-game is the activity format; a profile is local; progress is a stored current state. Define score, attempt and percentage using Christian and Sean&#39;s agreed data meanings.</p><h2 id="chapter-iii--design-and-methodology">Chapter III — Design and methodology<a class="header-anchor" href="#chapter-iii--design-and-methodology" aria-label="Link to this section">​</a></h2><p>The development approach is to finish and test a small complete increment, then reuse its shared systems. The first complete increment is Quiz with local save/reload. Wordle and BlockMatch follow the agreed manager, content and persistence boundaries. Integration and device testing precede the fixed November 3–6 beta.</p><p>The system has presentation, game-logic and data layers. Input commands reach Game Manager through the Event Bus; one active mini-game processes play. Progress Manager coordinates records through Database Manager and SQLite. UI Manager presents state and save outcomes.</p><p>The evaluation must distinguish technical operation, usability and learning evidence. Respondents, sampling, sample size, approved instruments, assistance policy and analysis method remain for school/adviser confirmation. A pre/post procedure is a recommendation if the approved study measures learning change; it is not an already approved design or completed session.</p><p>Required source material: <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/requirements/product-requirements.html">requirements</a>, <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/game-design.html">GDD</a>, <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/design/app-flow.html">flow</a>, <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/design/database-schema.html">data</a>, <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/hardware-validation.html">devices</a>, <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/kanban-plan-draft.html">task plan</a>, <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/qa-evaluation.html">evaluation</a>. Cite actual build/screens/tests when describing the implemented prototype. Preserve the school&#39;s unresolved wording “ISO 2010” until its instrument is identified.</p><h2 id="chapters-ivv--results-and-conclusions">Chapters IV–V — Results and conclusions<a class="header-anchor" href="#chapters-ivv--results-and-conclusions" aria-label="Link to this section">​</a></h2><p>Write results only from actual preliminary/system evaluation and technical tests. Record the delivered build, participant context, usable and missing records, analysis method and limitations. Keep raw participant records and identifying documents in the approved restricted location.</p><p>Conclusions must answer the objectives to the extent supported by those results. Completion and enjoyment alone do not prove learning gains; a simple observed pre/post change does not by itself establish causation.</p><p>The fixed pre-final is November 21, 2026. Plan actual beta analysis November 7–13, manuscript assembly November 14–16 and rehearsal November 17–20. Missing required evidence remains a delivery issue, not a result to invent.</p></div>',1)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
